create table if not exists public.buildpulse_document_sequences(entity_id uuid not null references public.buildpulse_accounting_entities(id) on delete cascade,document_type text not null check(document_type in ('invoice','credit_note','receipt')),fiscal_year integer not null,last_number bigint not null default 0,primary key(entity_id,document_type,fiscal_year));
alter table public.buildpulse_document_sequences enable row level security;revoke all on public.buildpulse_document_sequences from anon,authenticated;grant all on public.buildpulse_document_sequences to service_role;
create or replace function public.buildpulse_next_document_number(p_entity_id uuid,p_document_type text,p_issued_at timestamptz default now()) returns text language plpgsql security definer set search_path=public as $$ declare y integer;n bigint;prefix text; begin if p_document_type not in ('invoice','credit_note','receipt') then raise exception 'invalid_document_type';end if;y:=extract(year from p_issued_at at time zone 'UTC')::integer;insert into public.buildpulse_document_sequences(entity_id,document_type,fiscal_year,last_number) values(p_entity_id,p_document_type,y,1) on conflict(entity_id,document_type,fiscal_year) do update set last_number=public.buildpulse_document_sequences.last_number+1 returning last_number into n;prefix:=case p_document_type when 'invoice' then 'INV' when 'credit_note' then 'CRN' else 'RCT' end;return 'BP-'||y::text||'-'||prefix||'-'||lpad(n::text,7,'0');end $$;
revoke all on function public.buildpulse_next_document_number(uuid,text,timestamptz) from public;grant execute on function public.buildpulse_next_document_number(uuid,text,timestamptz) to service_role;